def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit needed to transform s_in into s_out."""
    # Find first difference
    pos = -1
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # Strings are identical up to min length
        if len(s_in) == len(s_out):
            return "", "", -1
        elif len(s_in) > len(s_out):
            # Remove from s_in
            old_sub = s_in[len(s_out):]
            new_sub = ""
            return old_sub, new_sub, len(s_out)
        else:
            # Insert into s_in
            new_sub = s_out[len(s_in):]
            old_sub = ""
            return old_sub, new_sub, len(s_in)

    # Return single character change for now
    old_char = s_in[pos]
    new_char = s_out[pos]
    return old_char, new_char, pos

def propose_rule_candidates(s_in, s_out):
    """Generate candidate replacement rules from a transformation."""
    candidates = []

    # Try single character replacements at each position
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            old_char = s_in[i]
            new_char = s_out[i]
            candidates.append((old_char, new_char))

    # Try multi-character replacements  
    for length in range(3, 0, -1):
        if len(s_in) >= length and len(s_out) >= length:
            for i in range(len(s_in) - length + 1):
                old_sub = s_in[i:i+length]
                if i + length <= len(s_out):
                    new_sub = s_out[i:i+length]
                    if old_sub != new_sub:
                        candidates.append((old_sub, new_sub))

    # Remove duplicates while preserving order
    seen = set()
    unique_candidates = []
    for cand in candidates:
        if cand not in seen:
            seen.add(cand)
            unique_candidates.append(cand)

    return unique_candidates

def apply_rules(strings, rules):
    """Apply a sequence of replacement rules to strings."""
    results = []
    for s in strings:
        result = s
        for pattern, replacement in rules:
            result = result.replace(pattern, replacement)
        results.append(result)
    return results

def score_rules(inputs, outputs, rules):
    """Score how well rules transform inputs to outputs."""
    results = apply_rules(inputs, rules)
    correct = sum(1 for i, o in zip(results, outputs) if i == o)
    return correct / len(outputs)

def find_over_applications(inputs, outputs, rules):
    """Find which examples are incorrectly modified by rules."""
    results = apply_rules(inputs, rules)
    over_apps = []
    for i, (inp, outp, res) in enumerate(zip(inputs, outputs, results)):
        if res != outp:
            over_apps.append((i, inp, res))
    return over_apps

