outputs = ['xfgb', 'zvfgvfgevhz', 'xyiu', 'uyeby', 'fgibu']

changed = find_changed_pairs(inputs, outputs)
print("Changed pairs:", changed)

# Build rules one by one
rules = []

# Let's try to build the rules systematically
for idx, s_in, s_out in changed:
    print(f"\nAnalyzing pair {idx}: '{s_in}' -> '{s_out}'")

    # Get candidates for this transformation
    candidates = propose_rule_candidates(s_in, s_out)
    print(f"Candidates: {candidates}")

    # Try each candidate in order
    for pattern, replacement in candidates:
        # Temporarily add this rule
        temp_rules = rules + [(pattern, replacement)]

        # Check if it causes over-applications
        over_apps = find_over_applications(inputs, outputs, temp_rules)

        if not over_apps:
            print(f"  Adding rule: replace('{pattern}', '{replacement}')")
            rules.append((pattern, replacement))
            break
        else:
            print(f"  Skipping rule replace('{pattern}', '{replacement}') - over-applies to {over_apps}")

print(f"\nFinal rules: {rules}")
print(f"Score: {score_rules(inputs, outputs, rules)}")

# Test the final solution
final_results = apply_rules(inputs, rules)
print(f"Results: {final_results}")
print(f"Expected: {outputs}")

